  "AI Chat": "\u0645\u062D\u0627\u062F\u062B\u0629 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A",
  "Use the AI Assistant panel on the right to chat!": "\u0627\u0633\u062A\u062E\u062F\u0645 \u0644\u0648\u062D\u0629 \u0645\u0633\u0627\u0639\u062F \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A \u0639\u0644\u0649 \u0627\u0644\u064A\u0645\u064A\u0646 \u0644\u0644\u062F\u0631\u062F\u0634\u0629!",
  "Subscription": "\u0627\u0644\u0627\u0634\u062A\u0631\u0627\u0643",
  "Manage your plan and billing.": "\u0623\u062F\u0631 \u062E\u0637\u062A\u0643 \u0648\u0627\u0644\u0641\u0648\u062A\u0631\u0629.",
  "Support": "\u0627\u0644\u062F\u0639\u0645",
  "Get help, browse docs, or contact our team.": "\u0627\u062D\u0635\u0644 \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u0627\u0639\u062F\u0629 \u0623\u0648 \u062A\u0635\u0641\u062D \u0627\u0644\u0645\u0633\u062A\u0646\u062F\u0627\u062A \u0623\u0648 \u062A\u0648\u0627\u0635\u0644 \u0645\u0639 \u0641\u0631\u064A\u0642\u0646\u0627.",
  "Keyboard Shortcuts": "\u0627\u062E\u062A\u0635\u0627\u0631\u0627\u062A \u0644\u0648\u062D\u0629 \u0627\u0644\u0645\u0641\u0627\u062A\u064A\u062D",
  "About Tayar Intelligence": "\u062D\u0648\u0644 Tayar Intelligence",
  "A focused workspace for building, creating, collaborating and shipping finished work.": "\u0645\u0633\u0627\u062D\u0629 \u0639\u0645\u0644 \u0645\u0631\u0643\u0632\u0629 \u0644\u0644\u0628\u0646\u0627\u0621 \u0648\u0627\u0644\u0625\u0646\u0634\u0627\u0621 \u0648\u0627\u0644\u062A\u0639\u0627\u0648\u0646 \u0648\u062A\u0633\u0644\u064A\u0645 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0646\u0647\u0627\u0626\u064A.",
  "Tayar Intelligence brings practical productivity tools into one workspace. The current product includes Website Builder V1, team workspaces, document and writing tools, translation, study workflows, project management and account-level preferences.": "\u064A\u062C\u0645\u0639 Tayar Intelligence \u0623\u062F\u0648\u0627\u062A \u0625\u0646\u062A\u0627\u062C\u064A\u0629 \u0639\u0645\u0644\u064A\u0629 \u0641\u064A \u0645\u0633\u0627\u062D\u0629 \u0639\u0645\u0644 \u0648\u0627\u062D\u062F\u0629. \u064A\u062A\u0636\u0645\u0646 \u0627\u0644\u0645\u0646\u062A\u062C \u0627\u0644\u062D\u0627\u0644\u064A \u0645\u0646\u0634\u0626 \u0627\u0644\u0645\u0648\u0627\u0642\u0639 V1 \u0648\u0645\u0633\u0627\u062D\u0627\u062A \u0639\u0645\u0644 \u0627\u0644\u0641\u0631\u0642 \u0648\u0623\u062F\u0648\u0627\u062A \u0627\u0644\u0645\u0633\u062A\u0646\u062F\u0627\u062A \u0648\u0627\u0644\u0643\u062A\u0627\u0628\u0629 \u0648\u0627\u0644\u062A\u0631\u062C\u0645\u0629 \u0648\u0633\u064A\u0631 \u0627\u0644\u062F\u0631\u0627\u0633\u0629 \u0648\u0625\u062F\u0627\u0631\u0629 \u0627\u0644\u0645\u0634\u0627\u0631\u064A\u0639 \u0648\u062A\u0641\u0636\u064A\u0644\u0627\u062A \u0627\u0644\u062D\u0633\u0627\u0628.",
  "The goal is simple: reduce tool switching while keeping the important parts of a project \u2014 content, versions, permissions and delivery \u2014 connected.": "\u0627\u0644\u0647\u062F\u0641 \u0628\u0633\u064A\u0637: \u062A\u0642\u0644\u064A\u0644 \u0627\u0644\u062A\u0646\u0642\u0644 \u0628\u064A\u0646 \u0627\u0644\u0623\u062F\u0648\u0627\u062A \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0627\u0644\u0623\u062C\u0632\u0627\u0621 \u0627\u0644\u0645\u0647\u0645\u0629 \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u2014 \u0627\u0644\u0645\u062D\u062A\u0648\u0649 \u0648\u0627\u0644\u0625\u0635\u062F\u0627\u0631\u0627\u062A \u0648\u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0627\u062A \u0648\u0627\u0644\u062A\u0633\u0644\u064A\u0645 \u2014 \u0645\u062A\u0631\u0627\u0628\u0637\u0629.",
  "Website Builder V1": "\u0645\u0646\u0634\u0626 \u0627\u0644\u0645\u0648\u0627\u0642\u0639 V1",
  "Website Builder V1 is active and supports responsive pages, forms, publishing, release history and rollback, multilingual pages, analytics, conversion tracking, lead management, team collaboration and client handoff workflows.": "\u0645\u0646\u0634\u0626 \u0627\u0644\u0645\u0648\u0627\u0642\u0639 V1 \u0641\u0639\u0627\u0644 \u0648\u064A\u062F\u0639\u0645 \u0627\u0644\u0635\u0641\u062D\u0627\u062A \u0627\u0644\u0645\u062A\u062C\u0627\u0648\u0628\u0629 \u0648\u0627\u0644\u0646\u0645\u0627\u0630\u062C \u0648\u0627\u0644\u0646\u0634\u0631 \u0648\u0633\u062C\u0644 \u0627\u0644\u0625\u0635\u062F\u0627\u0631\u0627\u062A \u0648\u0627\u0644\u0627\u0633\u062A\u0631\u062C\u0627\u0639 \u0648\u0627\u0644\u0635\u0641\u062D\u0627\u062A \u0645\u062A\u0639\u062F\u062F\u0629 \u0627\u0644\u0644\u063A\u0627\u062A \u0648\u0627\u0644\u062A\u062D\u0644\u064A\u0644\u0627\u062A \u0648\u062A\u062A\u0628\u0639 \u0627\u0644\u062A\u062D\u0648\u064A\u0644\u0627\u062A \u0648\u0625\u062F\u0627\u0631\u0629 \u0627\u0644\u0639\u0645\u0644\u0627\u0621 \u0627\u0644\u0645\u062D\u062A\u0645\u0644\u064A\u0646 \u0648\u062A\u0639\u0627\u0648\u0646 \u0627\u0644\u0641\u0631\u0642 \u0648\u062A\u0633\u0644\u064A\u0645 \u0627\u0644\u0639\u0645\u0644\u0627\u0621.",
  "What comes next": "\u0645\u0627 \u0627\u0644\u062A\u0627\u0644\u064A",
  "The next major product phase is AI-assisted website generation. It is intentionally separate from V1 so the core builder can remain useful and production-ready without depending on AI generation.": "\u0627\u0644\u0645\u0631\u062D\u0644\u0629 \u0627\u0644\u0631\u0626\u064A\u0633\u064A\u0629 \u0627\u0644\u062A\u0627\u0644\u064A\u0629 \u0647\u064A \u0625\u0646\u0634\u0627\u0621 \u0627\u0644\u0645\u0648\u0627\u0642\u0639 \u0628\u0645\u0633\u0627\u0639\u062F\u0629 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A. \u0648\u0647\u064A \u0645\u0646\u0641\u0635\u0644\u0629 \u0639\u0645\u062F\u0627\u064B \u0639\u0646 V1 \u0644\u064A\u0628\u0642\u0649 \u0627\u0644\u0645\u0646\u0634\u0626 \u0627\u0644\u0623\u0633\u0627\u0633\u064A \u0645\u0641\u064A\u062F\u0627\u064B \u0648\u062C\u0627\u0647\u0632\u0627\u064B \u0644\u0644\u0625\u0646\u062A\u0627\u062C \u062F\u0648\u0646 \u0627\u0644\u0627\u0639\u062A\u0645\u0627\u062F \u0639\u0644\u0649 \u0627\u0644\u062A\u0648\u0644\u064A\u062F \u0628\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A.",
  "Contact Us": "\u0627\u062A\u0635\u0644 \u0628\u0646\u0627",
  "We'd love to hear from you. Reach out with any questions or feedback.": "\u064A\u0633\u0639\u062F\u0646\u0627 \u0633\u0645\u0627\u0639\u0643. \u062A\u0648\u0627\u0635\u0644 \u0645\u0639\u0646\u0627 \u0628\u0623\u064A \u0623\u0633\u0626\u0644\u0629 \u0623\u0648 \u0645\u0644\u0627\u062D\u0638\u0627\u062A.",
