  "Select a linked component instance first": "\u0627\u062E\u062A\u0631 \u0646\u0633\u062E\u0629 \u0645\u0643\u0648\u0646 \u0645\u0631\u062A\u0628\u0637\u0629 \u0623\u0648\u0644\u064B\u0627",
