  "Select a section or element first": "\u0627\u062E\u062A\u0631 \u0642\u0633\u0645\u064B\u0627 \u0623\u0648 \u0639\u0646\u0635\u0631\u064B\u0627 \u0623\u0648\u0644\u064B\u0627",
  "Component": "\u0645\u0643\u0648\u0646",
  "Delete component": "\u062D\u0630\u0641 \u0627\u0644\u0645\u0643\u0648\u0646",
  "DEL": "\u062D\u0630\u0641",
  "Select an element on the canvas, then choose \u201CCreate component\u201D.": "\u0627\u062E\u062A\u0631 \u0639\u0646\u0635\u0631\u064B\u0627 \u0639\u0644\u0649 \u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0639\u0645\u0644\u060C \u062B\u0645 \u0627\u062E\u062A\u0631 \xAB\u0625\u0646\u0634\u0627\u0621 \u0645\u0643\u0648\u0646\xBB.",
  "Select a section or an element on the canvas before inserting a component.": "\u0627\u062E\u062A\u0631 \u0642\u0633\u0645\u064B\u0627 \u0623\u0648 \u0639\u0646\u0635\u0631\u064B\u0627 \u0639\u0644\u0649 \u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0639\u0645\u0644 \u0642\u0628\u0644 \u0625\u062F\u0631\u0627\u062C \u0645\u0643\u0648\u0646.",
