  "Custom": "\u0645\u062E\u0635\u0635",
  "Built-in": "\u0645\u062F\u0645\u062C",
  "Remove model": "\u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0646\u0645\u0648\u0630\u062C",
