  "Selected": "\u0645\u062D\u062F\u062F",
  "Provider": "\u0627\u0644\u0645\u0632\u0648\u0651\u062F",
  "Saved here as an admin content draft. Public pages are not changed until live-content wiring is enabled.": "\u0645\u062D\u0641\u0648\u0638 \u0647\u0646\u0627 \u0643\u0645\u0633\u0648\u062F\u0629 \u0645\u062D\u062A\u0648\u0649 \u0644\u0644\u0625\u062F\u0627\u0631\u0629. \u0644\u0627 \u062A\u062A\u063A\u064A\u0631 \u0627\u0644\u0635\u0641\u062D\u0627\u062A \u0627\u0644\u0639\u0627\u0645\u0629 \u062D\u062A\u0649 \u064A\u062A\u0645 \u062A\u0641\u0639\u064A\u0644 \u0631\u0628\u0637 \u0627\u0644\u0645\u062D\u062A\u0648\u0649 \u0627\u0644\u0645\u0628\u0627\u0634\u0631.",
  "Dashboard data unavailable": "\u0628\u064A\u0627\u0646\u0627\u062A \u0644\u0648\u062D\u0629 \u0627\u0644\u062A\u062D\u0643\u0645 \u063A\u064A\u0631 \u0645\u062A\u0627\u062D\u0629",
  "The admin data source could not be loaded.": "\u062A\u0639\u0630\u0631 \u062A\u062D\u0645\u064A\u0644 \u0645\u0635\u062F\u0631 \u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0625\u062F\u0627\u0631\u0629.",
  "Admin Data Status": "\u062D\u0627\u0644\u0629 \u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0625\u062F\u0627\u0631\u0629",
  "Only verified live data is shown here; placeholder health metrics have been removed.": "\u064A\u062A\u0645 \u0639\u0631\u0636 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0645\u0628\u0627\u0634\u0631\u0629 \u0627\u0644\u062A\u064A \u062A\u0645 \u0627\u0644\u062A\u062D\u0642\u0642 \u0645\u0646\u0647\u0627 \u0641\u0642\u0637 \u0647\u0646\u0627\u061B \u0648\u0642\u062F \u062A\u0645\u062A \u0625\u0632\u0627\u0644\u0629 \u0645\u0642\u0627\u064A\u064A\u0633 \u0627\u0644\u0635\u062D\u0629 \u0627\u0644\u0648\u0647\u0645\u064A\u0629.",
